const INSIDE_HALF_WIDTH = (INSIDE_FULL_WIDTH - SPC) / 2;
const INSIDE_HEIGHT = GROUP_HEIGHT - (MRG * 2);
const BIG_GROUP_WIDTH = (SMALL_GROUP_WIDTH * 2) + SPC;
const WIN_WIDTH = (MRG * 2) + BIG_GROUP_WIDTH;
const WIN_HEIGHT = TOP_MRG + MRG + LOGO_HEIGHT + (GROUP_HEIGHT * GROUPS_NUMBER) + (SPC * (GROUPS_NUMBER - 1)) + LOGO_SPC;
const FULL_BOUNDS = [0, 0, BIG_GROUP_WIDTH, GROUP_HEIGHT];
const HALF_BOUNDS_L = [0, 0, SMALL_GROUP_WIDTH, GROUP_HEIGHT];
const HALF_BOUNDS_R = [SMALL_GROUP_WIDTH + SPC, 0, (SMALL_GROUP_WIDTH * 2) + SPC, GROUP_HEIGHT];
const INSIDE_FULL_BOUNDS = [MRG, MRG, INSIDE_FULL_WIDTH, MRG + INSIDE_HEIGHT];
const INSIDE_HALF_BOUNDS_L = [MRG, MRG, INSIDE_HALF_WIDTH, MRG + INSIDE_HEIGHT];
const INSIDE_HALF_BOUNDS_R = [MRG + INSIDE_HALF_WIDTH + SPC, MRG, MRG + (INSIDE_HALF_WIDTH * 2) + SPC, MRG + INSIDE_HEIGHT];
