function checkForNewVersion(checkNow) {
function showNewVersionUI(versionDifference) {
return (versionDifference > 0) && (((((lastVersionChecked == undefined) || (lastTimeVersionChecked == undefined)) || (nextTimeVersionChecked == undefined)) || (checkNow)) || (currentTime >= nextTimeVersionChecked));
}
if (checkNow == undefined) { 
checkNow = false;
}
if (!doUpdateCheck) { 
return;
}
if (haveSettings(prefsSectionName, prefsLastVersionChecked)) { 
lastVersionChecked = getSettings(prefsSectionName, prefsLastVersionChecked);
}
if (haveSettings(prefsSectionName, prefsLastServerVersionChecked)) { 
lastServerVersionChecked = getSettings(prefsSectionName, prefsLastServerVersionChecked);
}
if (haveSettings(prefsSectionName, prefsLastTimeVersionChecked)) { 
lastTimeVersionChecked = new Date(getSettings(prefsSectionName, prefsLastTimeVersionChecked));
}
if (haveSettings(prefsSectionName, prefsNextTimeVersionCheckedSkipVersion)) { 
nextTimeVersionCheckedSkipVersion = getSettings(prefsSectionName, prefsNextTimeVersionCheckedSkipVersion);
}
if (haveSettings(prefsSectionName, prefsNextTimeVersionChecked)) { 
nextTimeVersionChecked = new Date(getSettings(prefsSectionName, prefsNextTimeVersionChecked));
}
if (haveSettings(prefsSectionName, prefsVersionCheckInit)) { 
versionCheckInit = getSettings(prefsSectionName, prefsVersionCheckInit);
}
var currentTime = new Date();
if ((((!checkNow) && (versionCheckInit != undefined)) && (nextTimeVersionChecked != undefined)) && (currentTime < nextTimeVersionChecked)) { 
return;
}
var serverVersionCheck = versionCheck(str.SKU, true, checkNow);
if (serverVersionCheck == null) { 
if (checkNow) { 
alert(str.UpdateCheckError);
}
return;
}
var serverVersion = (serverVersionCheck != null) && (serverVersionCheck.hasOwnProperty("version")) ? serverVersionCheck.version : str.ScriptVersion;
if (((!checkNow) && (lastServerVersionChecked != undefined)) && (lastServerVersionChecked == serverVersion)) { 
return;
}
if (((!checkNow) && (nextTimeVersionCheckedSkipVersion != undefined)) && (nextTimeVersionCheckedSkipVersion == lastServerVersionChecked)) { 
return;
}
saveSettings(prefsSectionName, prefsVersionCheckInit, 1);
try {
var newDate = new Date();
newDate = dateAddDays(updateCheckInterval);
saveSettings(prefsSectionName, prefsLastVersionChecked, str.ScriptVersion);
saveSettings(prefsSectionName, prefsLastTimeVersionChecked, new Date().toString());
saveSettings(prefsSectionName, prefsNextTimeVersionChecked, newDate.toString());
} catch (e) {alert(e.toString());
}
var versionDifference = compareVersions(serverVersion, str.ScriptVersion);
var showNewVersion = showNewVersionUI(versionDifference);
if (showNewVersion) { 
newVersionUI(serverVersionCheck);
}
else {
if ((versionDifference <= 0) && (checkNow)) { 
alert(str.UpToDate);
}
}
}
function versionCheck(scriptSKU, latest, isCheckNow) {
var checkLatest = latest ? "&latest=1" : "";
var url = "https://notify.aescripts.com/versioncheck2.php?json=1&sku=" + scriptSKU + checkLatest;
var resp = extComms(url, isCheckNow);
if (((resp == null) || (resp == "")) || (validateJSON(resp) == false)) { 
if (isCheckNow) { 
alert(str.UpdateCheckError);
return null;
}
else {
return null;
}
}
try {
if (typeof JSON != "undefined") { 
resp = JSON.parse(resp);
}
else {
resp = JSONify(resp.replace(/\\u[0-9a-b]*/g, " "), "parse");
}
if (resp == null) { 
return null;
}
} catch (e) {return null;
}
if (resp.status != "ok") { 
return null;
}
if (latest) { 
version = {date: resp.latest.release_date, detail: resp.latest.detail, header: str.VersionRev.replace(/%a/, resp.version).replace(/%b/, "").replace(/%c/, resp.latest.release_date), version: resp.version};
}
else {
version = {version: resp.version};
}
return version;
}
function extComms(url, displayErrors, isAPI) {
if (isAPI == null) { 
isAPI = false;
}
if (isAPI) { 
args = url;
}
if (displayErrors == null) { 
displayErrors = true;
}
try {
var newExe = create_altool();
if (!newExe.exists) { 
var title = "extComms error. alttool does not exists";
var detail = "alttool does not exists. Please click on \'Open Support Ticket\' button for assistance.";
var errDetail = "e" in licenseValidity ? "\n" + licenseValidity.e : "";
var licError = "title" in licenseValidity ? " - " + licenseValidity.title : "";
var url = createSupportTicket({message: errDetail, subject: title + licError});
alertButtonsUI(title, detail, {name: "Open Support Ticket", url: url}, {name: str.Cancel});
return null;
}
var newExePath = newExe.fsName;
if (isAPI) { 
cmd = "\"" + newExePath + "\" -web " + args + "";
}
else {
cmd = "\"" + newExePath + "\" -web \"" + url + "\"";
}
var res = systemCall(cmd);
newExe.remove();
var lines = res.match(/[^\r\n]+/g);
var http_response_code = lines[0];
if ((lines.length > 0) && (http_response_code == "200")) { 
if (isAPI) { 
return res;
}
if (lines.length >= 1) { 
return lines[1];
}
else {
alertButtonsUI("extComms error", "Empty Payload. Please click on \'Open Support Ticket\' button for assistance.", {name: "Open Support Ticket", url: url}, {name: str.Cancel});
return null;
}
}
else {
if (isAPI) { 
return {code: http_response_code, payload: lines.join("")};
}
else {
if (displayErrors) { 
alertButtonsUI("extComms error", res.toString() + "\n\nPlease click on \'Open Support Ticket\' button for assistance.", {name: "Open Support Ticket", url: url}, {name: str.Cancel});
}
return null;
}
}
} catch (e) {if (isAPI) { 
return {code: "000", payload: e};
}
else {
alert("extComms error\n" + e.toString());
return null;
}
}
}
