function formatHistory(notes, clientVersion) {
var data = notes.data;
var releaseNotesFormatted = [];
for (var m1 in data) { 
if (!data.hasOwnProperty(m1)) { 
continue ;
}
var history = data[m1].history;
for (var i = history.length - 1; i >= 0; i--) { 
var rel = history[i];
var isCurrentVersionNote = "";
var detail = rel.detail;
if (i == (history.length - 1)) { 
isCurrentVersionNote = " (" + str.NewestVersionAvailable + ")";
}
var myVersionFormatted = str.VersionRev.replace(/%0/, rel.version_number).replace(/%1/, isCurrentVersionNote).replace(/%2/, rel.release_date).replace(/%3/, detail);
if ((!options.summaryOnlyNewChanges) || (compareVersions(clientVersion, rel.version_number) < 0)) { 
releaseNotesFormatted.push(myVersionFormatted);
}}
}
var result = releaseNotesFormatted.join("\n\n");
return result;
}
